import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Blacksmithing","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/blacksmithing.md","filePath":"es/game-design/professions/blacksmithing.md"}'),r={name:"es/game-design/professions/blacksmithing.md"};function s(l,e,t,c,d,m){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="blacksmithing" tabindex="-1">Blacksmithing <a class="header-anchor" href="#blacksmithing" aria-label="Enlace permanente a &quot;Blacksmithing&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y vías de técnicas siguientes siguen siendo candidatos. <strong>Implementación:</strong> este batch documental no establece implementación de este rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de gameplay. <strong>Revisado:</strong> 2026-10-09 para la proyección pública; estado del diseño y mecánicas conservados de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Panorama para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Blacksmithing debería ser metalurgia y transformación del metal, no &quot;lingotes -&gt; objeto&quot;.</p><h3 id="core-chain" tabindex="-1">Cadena principal <a class="header-anchor" href="#core-chain" aria-label="Enlace permanente a &quot;Cadena principal&quot;">​</a></h3><p>Fundición -&gt; Refinado -&gt; Aleación -&gt; Conformado/Forjado -&gt; Tratamiento térmico -&gt; Acabado -&gt; Mantenimiento</p><h3 id="possible-stages" tabindex="-1">Etapas posibles <a class="header-anchor" href="#possible-stages" aria-label="Enlace permanente a &quot;Etapas posibles&quot;">​</a></h3><ul><li>fundición del mineral;</li><li>masa de metal bruto/metal crudo;</li><li>refinado de impurezas;</li><li>aleación;</li><li>conformado en forja;</li><li>tratamiento térmico;</li><li>acabado.</li></ul><h3 id="material-and-process-influences" tabindex="-1">Influencias del material y el proceso <a class="header-anchor" href="#material-and-process-influences" aria-label="Enlace permanente a &quot;Influencias del material y el proceso&quot;">​</a></h3><ul><li>dureza;</li><li>tenacidad;</li><li>flexibilidad;</li><li>peso;</li><li>desgaste;</li><li>comportamiento de corte/penetración/golpe contundente.</li></ul><p>No convertirlas en decenas de atributos expuestos.</p><h3 id="forging-interface" tabindex="-1">Interfaz de forja <a class="header-anchor" href="#forging-interface" aria-label="Enlace permanente a &quot;Interfaz de forja&quot;">​</a></h3><ul><li>fragua/fuego;</li><li>yunque;</li><li>enfriamiento;</li><li>herramientas;</li><li>zonas de trabajo/operaciones de conformado.</li></ul><h3 id="potential-forging-operations" tabindex="-1">Operaciones potenciales de forjado <a class="header-anchor" href="#potential-forging-operations" aria-label="Enlace permanente a &quot;Operaciones potenciales de forjado&quot;">​</a></h3><ul><li>estirar;</li><li>aplanar;</li><li>ahusar;</li><li>doblar;</li><li>punzonar;</li><li>acanalar.</li></ul><h3 id="heat-treatment" tabindex="-1">Tratamiento térmico <a class="header-anchor" href="#heat-treatment" aria-label="Enlace permanente a &quot;Tratamiento térmico&quot;">​</a></h3><ul><li>temple;</li><li>revenido;</li><li>recocido;</li><li>otras técnicas si se justifican después.</li></ul><h3 id="tradeoffs-matter" tabindex="-1">Las contrapartidas importan <a class="header-anchor" href="#tradeoffs-matter" aria-label="Enlace permanente a &quot;Las contrapartidas importan&quot;">​</a></h3><ul><li>filo más duro frente a fragilidad;</li><li>tenacidad frente a capacidad máxima de corte;</li><li>peso frente a durabilidad;</li></ul><p>etc.</p><p>La calidad excepcional debería surgir del proceso/material/habilidad, no de una simple tirada aleatoria &quot;Exceptional&quot;.</p><h3 id="field-utility" tabindex="-1">Utilidad en el terreno <a class="header-anchor" href="#field-utility" aria-label="Enlace permanente a &quot;Utilidad en el terreno&quot;">​</a></h3><ul><li>evaluación de equipo;</li><li>mantenimiento de campaña;</li><li>afilado;</li><li>reparaciones menores;</li><li>conocimiento estructural/material.</li></ul><h3 id="cross-skill" tabindex="-1">Entre habilidades <a class="header-anchor" href="#cross-skill" aria-label="Enlace permanente a &quot;Entre habilidades&quot;">​</a></h3><ul><li>Arms Lore = comprensión marcial de cómo rinde un arma;</li><li>Blacksmithing = comprensión material/estructural;</li><li>juntas proporcionan una evaluación más rica.</li></ul><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Metallurgical Journal.</strong> Bladesmithing y Armorsmithing son ejemplos concretos de técnicas. Los materiales, la comprensión del proceso y la práctica pueden crear identidades de armas duraderas de campaña o armadura ligera.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define enseñanza y dirección de límite/progreso. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, conocimiento compartido, dominio manual, producción por lotes, encargos y reputación multidimensional. Esas reglas no se redefinen aquí de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define los límites compartidos de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en el terreno <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en el terreno&quot;">​</a></h2><p>Mining aporta procedencia geológica; Arms Lore contribuye conocimiento del uso marcial mientras Blacksmithing aporta evaluación material/estructural. Carpentry y Tailoring pueden contribuir componentes compuestos; Tinkering puede necesitar armazones y armadura.</p><p><a href="/Syrolands-Public/es/game-design/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">Arms Lore y funciones de habilidades</a> · <a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">Equipo y botín</a> · Adaptador de armadura · <a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Carpentry</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar solo estado e información que apoyen decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Aquí no se eligen identificadores de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Familias de materiales y recetas de aleaciones; intervalos significativos del proceso; información del tratamiento térmico; límites de reparación y costes materiales; límites de información de evaluación; cómo las dimensiones compactas de calidad se relacionan con rendimiento de armaduras/armas. No se elige nueva fórmula de absorción ni tirada Exceptional.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y la evidencia de combate existentes no validan este rediseño de profesiones.</p>',38)])])}const h=a(r,[["render",s]]);export{u as __pageData,h as default};
